f.assertTensorClose(hyperbolic.hyperbolic_distance(ball([[0.0, 0.0]]), ball([[0.0, 0.6]])), [[2.0 * math.atanh(0.6)]])\n\n    def test_projection_and_boundary_clamp(self):\n        projected = hyperbolic.project_to_ball(ball([[3.0, 4.0]]))\n        self.assertTensorClose(projected, [[0.6 * (1.0 - 1e-6), 0.8 * (1.0 - 1e-6)]])\n        d = hyperbolic.hyperbolic_distance(ball([[0.0]]), ball([[1.0]]))\n        self.assertTrue(torch.isfinite(d).all())\n        self.assertTensorClose(d, [[2.0 * math.atanh(1.0 - 1e-6)]], atol=1e-8)\n\n\nif __name__ == '__main__':\n    unittest.main()\n","falsifiers":["exp_0 fails the independently derived tanh radial map, or log_0(exp_0(v)) fails to recover non-boundary tangent values (including zero).","Mobius addition disagrees with the closed-form collinear composition (a+b)/(1+ab).","Hyperbolic distance disagrees with the curvature -1 diameter identity D(tanh(u),tanh(v))=2|u-v| or is not symmetric on interior points.","Ball projection changes direction or fails to clamp radius to 1-EPSILON; boundary distance becomes non-finite or differs from the finite clamp reference."]}
